import{_ as t,o,c,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant API v1 — Contacts","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Contacts | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-contacts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Contacts | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-contacts"}]]},"headers":[],"relativePath":"api/tenant-v1-contacts.md","filePath":"api/tenant-v1-contacts.md","lastUpdated":1786669184000}'),d={name:"api/tenant-v1-contacts.md"};function n(s,e,i,r,l,h){return o(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-contacts" tabindex="-1">Tenant API v1 — Contacts <a class="header-anchor" href="#tenant-api-v1-—-contacts" aria-label="Permalink to &quot;Tenant API v1 — Contacts&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:contacts</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>contacts.assign</code> (and not superadmin), list/stats/view/update only include contacts where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-contacts-stats" tabindex="-1">GET <code>/contacts/stats</code> <a class="header-anchor" href="#get-contacts-stats" aria-label="Permalink to &quot;GET `/contacts/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_contacts</code>, <code>my_contacts</code>, <code>unassigned</code>, <code>with_email</code>, <code>created_this_week</code>, <code>on_boarded</code>, <code>off_boarded</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="contacts-crud" tabindex="-1">Contacts CRUD <a class="header-anchor" href="#contacts-crud" aria-label="Permalink to &quot;Contacts CRUD&quot;">​</a></h2><h3 id="get-contacts" tabindex="-1">GET <code>/contacts</code> <a class="header-anchor" href="#get-contacts" aria-label="Permalink to &quot;GET `/contacts`&quot;">​</a></h3><p>Query: <code>search</code>, <code>company</code>, <code>company_id</code>, <code>lifecycle_status</code> (<code>on_boarded</code> | <code>off_boarded</code>), <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_contacts</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>lifecycle_status</code>, <code>latest_note</code> — most recent note (<code>id</code>, <code>body</code>, <code>author</code>, timestamps) or <code>null</code>. May include <code>company_id</code> and <code>linked_company</code> when the relationship is loaded.</p><h3 id="post-contacts" tabindex="-1">POST <code>/contacts</code> <a class="header-anchor" href="#post-contacts" aria-label="Permalink to &quot;POST `/contacts`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>company</code> (legacy free-text), <code>company_id</code> (optional FK to Companies), <code>job_title</code>, <code>source</code>, <code>lifecycle_status</code> (default <code>on_boarded</code>), <code>assigned_to</code>.</p><p>When <code>company_id</code> is set and the company exists, the legacy <code>company</code> string is synced to that Company’s name.</p><h3 id="get-contacts-id" tabindex="-1">GET <code>/contacts/{id}</code> <a class="header-anchor" href="#get-contacts-id" aria-label="Permalink to &quot;GET `/contacts/{id}`&quot;">​</a></h3><p>Includes assignee, creator, notes, activities. May include <code>company_id</code> and <code>linked_company</code> (<code>id</code>, <code>uuid</code>, <code>name</code>) when the relationship is loaded.</p><h3 id="put-contacts-id" tabindex="-1">PUT <code>/contacts/{id}</code> <a class="header-anchor" href="#put-contacts-id" aria-label="Permalink to &quot;PUT `/contacts/{id}`&quot;">​</a></h3><p>Partial update of contact fields (including <code>assigned_to</code>, <code>company</code>, <code>company_id</code>).</p><h3 id="delete-contacts-id" tabindex="-1">DELETE <code>/contacts/{id}</code> <a class="header-anchor" href="#delete-contacts-id" aria-label="Permalink to &quot;DELETE `/contacts/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>contacts.delete</code>.</p><h3 id="post-contacts-id-restore" tabindex="-1">POST <code>/contacts/{id}/restore</code> <a class="header-anchor" href="#post-contacts-id-restore" aria-label="Permalink to &quot;POST `/contacts/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted contact. Permission: <code>contacts.restore</code>.</p><h3 id="delete-contacts-id-force" tabindex="-1">DELETE <code>/contacts/{id}/force</code> <a class="header-anchor" href="#delete-contacts-id-force" aria-label="Permalink to &quot;DELETE `/contacts/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted contact (must already be trashed). Permission: <code>contacts.force.delete</code> (owner by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-contacts-id-assign" tabindex="-1">POST <code>/contacts/{id}/assign</code> <a class="header-anchor" href="#post-contacts-id-assign" aria-label="Permalink to &quot;POST `/contacts/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><h3 id="post-contacts-id-notes" tabindex="-1">POST <code>/contacts/{id}/notes</code> <a class="header-anchor" href="#post-contacts-id-notes" aria-label="Permalink to &quot;POST `/contacts/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-contacts-id-timeline" tabindex="-1">GET <code>/contacts/{id}/timeline</code> <a class="header-anchor" href="#get-contacts-id-timeline" aria-label="Permalink to &quot;GET `/contacts/{id}/timeline`&quot;">​</a></h3><p>Contact activity timeline entries.</p><h2 id="lead-conversion" tabindex="-1">Lead conversion <a class="header-anchor" href="#lead-conversion" aria-label="Permalink to &quot;Lead conversion&quot;">​</a></h2><p><code>POST /leads/{lead}/convert</code> (see <a href="/api/tenant-v1-leads">tenant-v1-leads.md</a>) creates a Contact and sets <code>contact_id</code> / <code>contact</code> on the returned lead when the <code>contacts</code> module is entitled for the workspace. <code>conversion_meta.stub</code> is <code>false</code> in that case; it is <code>true</code> when Contacts is not installed (status-only conversion).</p>',34)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
